tasks = dict(zip(values('W0::Tasks', 'K420:K425'), values('W0::Tasks', 'L420:L425')))
deps = list(zip(values('W0::Dependencies', 'K38:K43'), values('W0::Dependencies', 'L38:L43')))
import collections
adj = collections.defaultdict(list)
indeg = {t: 0 for t in tasks}
for s, p in deps:
    adj[p].append(s)
    indeg[s] += 1
earliest = {t: 0 for t in tasks}
q = collections.deque([t for t in tasks if indeg[t] == 0])
while q:
    u = q.popleft()
    finish = earliest[u] + tasks[u]
    for v in adj[u]:
        if finish > earliest[v]:
            earliest[v] = finish
        indeg[v] -= 1
        if indeg[v] == 0:
            q.append(v)
result = max(earliest[t] + tasks[t] for t in tasks)

